public class Solution_2311 {

    public static void main(String[] args) {
        Solution_2311 sol = new Solution_2311();

        System.out.println(Math.pow(2, 1000) > Long.MAX_VALUE);
        System.out.println(sol.longestSubsequence(
//                "00101001", 1
//                "100110111111000000010011101000111011000001000111010001010111100001111110110010100011100100111000011011000000100001011000000100110110001101011010011", 522399436
                ""
                , 1
        ));
        System.out.println("==================");
    }

    public int longestSubsequence(String s, int k) {
        char[] cs = s.toCharArray();
        int n = 0;
        long base = 1;
        long sum = 0;
        boolean yes = false; // 判断是否溢出
        boolean[] vis = new boolean[cs.length];
        for (int i = cs.length - 1; i >= 0; i--) {

            if (cs[i] == '0') vis[i] = true;

            if (yes) continue;

            sum += base * (cs[i] - '0');
            if (sum <= k) vis[i] = true;
            else yes = true;

            base <<= 1;
            if (base > k) yes = true; // base> k , means don't need any 1.
        }

        int cnt = 0;
        for (int i = 0; i < vis.length; i++) {
            if (vis[i]) cnt++;
        }
        return cnt;
    }

}


